//! Team identity and the bundled `data/wvw-teams.json` table (ADR-010).
//!
//! The official API exposes team ids but not their names, so the names travel
//! inside the binary. A missing id is not an error: the UI falls back to the id.

use std::collections::{BTreeMap, HashMap};
use std::sync::OnceLock;

use serde::Deserialize;

/// Table shipped with the addon, regenerated by `scripts/update_wvw_teams.ps1`.
pub const BUNDLED_JSON: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../data/wvw-teams.json"
));

/// Curated translations, keyed by the **English** name.
///
/// Generated from `data/equipos.xlsx` by `scripts/merge_team_names.ps1`. Keyed by name and not
/// by id on purpose: WvW team names rotate every season while the ids stay, so a translation
/// must survive an id changing its name and come back if the name returns.
pub const NAMES_JSON: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../data/team-names.json"
));

/// One translation entry.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
pub struct TeamName {
    #[serde(default)]
    pub es: Option<String>,
    #[serde(default)]
    pub fr: Option<String>,
    #[serde(default)]
    pub de: Option<String>,
    /// Where the translation came from (`spreadsheet`, `game`…), so curated names can win.
    #[serde(default)]
    pub source: Option<String>,
}

impl TeamName {
    /// Translation for a two-letter language code, if there is one.
    pub fn get(&self, language: &str) -> Option<&str> {
        match language {
            "es" => self.es.as_deref(),
            "fr" => self.fr.as_deref(),
            "de" => self.de.as_deref(),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
struct NamesFile {
    #[serde(default)]
    names: BTreeMap<String, TeamName>,
}

/// Translations by English name, parsed once.
///
/// A broken file yields an empty map: the UI falls back to the English name, which is always
/// correct even if it is not translated (RNF-06).
pub fn translations() -> &'static BTreeMap<String, TeamName> {
    static NAMES: OnceLock<BTreeMap<String, TeamName>> = OnceLock::new();
    NAMES.get_or_init(|| {
        serde_json::from_str::<NamesFile>(NAMES_JSON)
            .map(|file| file.names)
            .unwrap_or_default()
    })
}

/// One entry of the table.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
pub struct TeamEntry {
    pub id: u32,
    pub name: String,
    #[serde(default)]
    pub nation: String,
    /// Names curated for other languages, keyed by two-letter code (`es`, `fr`, `de`).
    ///
    /// The API does not translate team names (`/v2/wvw/teams` is 404) and the game keeps them
    /// in client strings we cannot read, so any translation here is typed by a human and has
    /// to be preserved when the table is regenerated.
    #[serde(default)]
    pub names: BTreeMap<String, String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
struct File {
    #[serde(default)]
    teams: Vec<TeamEntry>,
}

/// Id -> name table for WvW teams.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct TeamTable {
    teams: HashMap<u32, TeamEntry>,
}

impl TeamTable {
    /// Parses the bundled table format. Unknown fields are ignored on purpose so
    /// the script can add metadata without breaking older builds.
    pub fn parse(json: &str) -> Result<Self, serde_json::Error> {
        let file: File = serde_json::from_str(json)?;
        let teams = file.teams.into_iter().map(|t| (t.id, t)).collect();
        Ok(Self { teams })
    }

    /// Name of the team, if known.
    pub fn name(&self, id: u32) -> Option<&str> {
        self.teams.get(&id).map(|t| t.name.as_str())
    }

    /// Region of the team as curated in the table (`EU`/`NA`), if known.
    pub fn nation(&self, id: u32) -> Option<&str> {
        self.teams.get(&id).map(|t| t.nation.as_str())
    }

    /// How the UI shows a team: `Name (id)`, or `(id)` when the name is unknown (RF-03a).
    pub fn label(&self, id: u32) -> String {
        match self.name(id) {
            Some(name) => format!("{name} ({id})"),
            None => format!("({id})"),
        }
    }

    /// Name of the team in a language, falling back to the curated English name.
    ///
    /// Three sources, most specific first: the `names` map of the entry itself (curated per
    /// id, what an official in-game name would be), the translation pool keyed by the English
    /// name, and finally English.
    pub fn name_in(&self, language: &str, id: u32) -> Option<&str> {
        let entry = self.teams.get(&id)?;
        if let Some(name) = entry.names.get(language) {
            return Some(name.as_str());
        }
        translations()
            .get(&entry.name)
            .and_then(|translation| translation.get(language))
            .or(Some(entry.name.as_str()))
    }

    /// `nombre (id)` in the requested language (RF-44), same fallback as [`Self::name_in`].
    pub fn label_in(&self, language: &str, id: u32) -> String {
        match self.name_in(language, id) {
            Some(name) => format!("{name} ({id})"),
            None => format!("({id})"),
        }
    }

    /// Number of known teams.
    pub fn len(&self) -> usize {
        self.teams.len()
    }

    /// Every team, ordered by region and then by name, for the picker (RF-03a).
    ///
    /// A stable order matters: an unsorted `HashMap` would make the list jump around
    /// between frames while the user is choosing.
    pub fn sorted(&self) -> Vec<&TeamEntry> {
        let mut teams: Vec<&TeamEntry> = self.teams.values().collect();
        teams.sort_by(|a, b| {
            a.nation
                .cmp(&b.nation)
                .then_with(|| a.name.cmp(&b.name))
                .then_with(|| a.id.cmp(&b.id))
        });
        teams
    }

    /// Whether the table is empty.
    pub fn is_empty(&self) -> bool {
        self.teams.is_empty()
    }
}

/// The bundled table, parsed once.
///
/// A broken JSON yields an empty table: showing ids beats crashing the game (RNF-06).
pub fn bundled() -> &'static TeamTable {
    static TABLE: OnceLock<TeamTable> = OnceLock::new();
    TABLE.get_or_init(|| TeamTable::parse(BUNDLED_JSON).unwrap_or_default())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rf03i_bundled_table_holds_every_live_team() {
        let table = bundled();
        assert_eq!(table.len(), 33, "15 NA + 18 EU as captured on 2026-10-31");
        assert_eq!(table.name(12014), Some("Great House Aviary"));
        assert_eq!(table.nation(12014), Some("EU"));
        assert_eq!(table.name(11001), Some("Moogooloo"));
        assert_eq!(table.name(999_999), None);
    }

    #[test]
    fn rf03a_label_falls_back_to_the_id_alone() {
        let table = bundled();
        assert_eq!(table.label(12014), "Great House Aviary (12014)");
        assert_eq!(table.label(12099), "(12099)");
    }

    #[test]
    fn rf44_translated_team_names_fall_back_to_english() {
        let json = r#"{ "teams": [
            { "id": 12014, "name": "Great House Aviary", "nation": "EU", "names": { "es": "Bosquemugoso" } },
            { "id": 11001, "name": "Moogooloo", "nation": "NA" }
        ] }"#;
        let table = TeamTable::parse(json).unwrap();

        assert_eq!(table.name_in("es", 12014), Some("Bosquemugoso"));
        assert_eq!(table.label_in("es", 12014), "Bosquemugoso (12014)");
        assert_eq!(
            table.name_in("fr", 11001),
            Some("Moogooloo"),
            "un nombre que no está en el Excel se queda en inglés"
        );
        assert_eq!(table.label_in("fr", 11001), "Moogooloo (11001)");
        assert_eq!(table.label_in("es", 99999), "(99999)");
        assert_eq!(
            table.name_in("it", 12014),
            Some("Great House Aviary"),
            "un idioma que no está en el mapa ni en el Excel cae al inglés"
        );
    }

    #[test]
    fn rf44_spreadsheet_names_are_used_by_english_name() {
        // 12010 is `Grenth's Door`; the spreadsheet translates that name, not that id.
        let table = bundled();
        assert_eq!(table.name_in("es", 12010), Some("Puerta de Grenth"));
        assert_eq!(table.name_in("de", 12010), Some("Grenths Tor"));
        assert_eq!(table.label_in("fr", 12010), "Porte de Grenth (12010)");

        // 12014 matches the spreadsheet too.
        assert_eq!(
            table.name_in("es", 12014),
            Some("Pajar de la Gran Casa"),
            "traduccion literal del Excel; el nombre oficial en el juego es otro"
        );

        // Lutgardis Conservatory is not in the spreadsheet: English, never empty.
        assert_eq!(table.name_in("es", 11011), Some("Lutgardis Conservatory"));
    }

    #[test]
    fn rf44_the_translation_pool_survives_a_seasonal_renaming() {
        // The pool is keyed by name, so a name that is not in use today is still translated
        // and will be found if that name comes back next season.
        let pool = translations();
        let old = pool
            .get("Zhaitan's Rest")
            .expect("nombre de una temporada anterior");
        assert_eq!(old.get("es"), Some("Reposo de Zhaitan"));

        let counts = pool.len();
        assert!(counts >= 20, "el Excel trae 21 filas: {counts}");
        assert!(pool
            .values()
            .all(|entry| entry.source.as_deref() == Some("spreadsheet")));
    }

    #[test]
    fn rf03a_picker_order_is_stable_and_regional() {
        let table = bundled();
        let teams = table.sorted();
        assert_eq!(teams.len(), table.len());

        let mut nations: Vec<&str> = Vec::new();
        for team in &teams {
            if nations.last() != Some(&team.nation.as_str()) {
                assert!(
                    !nations.contains(&team.nation.as_str()),
                    "la región {} aparece en dos bloques",
                    team.nation
                );
                nations.push(&team.nation);
            }
        }
        let mut ascending = nations.clone();
        ascending.sort_unstable();
        assert_eq!(nations, ascending, "las regiones van agrupadas y en orden");

        for nation in nations {
            let names: Vec<&str> = teams
                .iter()
                .filter(|team| team.nation == nation)
                .map(|team| team.name.as_str())
                .collect();
            let mut expected = names.clone();
            expected.sort_unstable();
            assert_eq!(names, expected, "dentro de {nation}, por nombre");
        }
    }

    #[test]
    fn rf03i_broken_table_degrades_to_ids() {
        assert!(TeamTable::parse("not json").is_err());
        let empty = TeamTable::parse(r#"{ "teams": [] }"#).unwrap();
        assert!(empty.is_empty());
        assert_eq!(empty.label(12014), "(12014)");
    }
}
